function fetchData(callback) {
  console.log('Fetching data...');
  setTimeout(() => {
    const data = { id: 1, name: 'Alice' };
    callback(data);
  }, 1000);
}

function handleData(data) {
  console.log('Received:', data.name);
}

fetchData(handleData);
console.log('Request sent!');

